const specialistForms=[{id:'brand',title:'your business profile & brand',intro:'understand what you offer, who you serve and how you want the business to be understood.',qs:[Q('business','what is your business name?'),Q('offer','what do you offer and who is the customer?','textarea'),Q('assets','which brand assets or profile do you already have?','textarea'),Q('goal','what should your audience understand or do next?','textarea')]},{id:'smart',title:'your smart-space or hardware need',intro:'start with the practical task. technical feasibility and site needs will be assessed before a recommendation.',qs:[Q('business','what name should we use for this enquiry?'),Q('space','what kind of space or task is involved?','textarea'),Q('problem','what should become easier, safer or more reliable?','textarea'),Q('existing','what equipment or automation already exists?','textarea'),Q('scope','where is the site and what is your intended timeframe?','textarea')]},{id:'opportunity',title:'your partnership & opportunity route',intro:'we check fit and readiness before recommending an application or partnership approach.',qs:[Q('business','what is the organisation or business name?'),Q('activity','what do you do and who benefits?','textarea'),Q('route','what are you exploring?','select',['partnership','grant opportunity','application support','help me choose']),Q('evidence','what experience, results or organisational documents already exist?','textarea'),Q('goal','what opportunity or outcome are you pursuing?','textarea')]}];if(!db.specialistForms){specialistForms.forEach(f=>{if(!db.forms.some(x=>x.id===f.id)){f.published={title:f.title,intro:f.intro,qs:structuredClone(f.qs),at:now()};db.forms.push(f)}});db.specialistForms=true;save()}
let brandV=null;
function brandFor(){if(['expertise','venture-page'].includes(route[0]))return db.ventures.find(v=>v.name===decodeURIComponent(route[1]||''));if(route[0]==='form'){let source=new URLSearchParams(location.hash.split('?')[1]||'').get('source')||'';let l=lead((route[2]||'').split('?')[0]);return db.ventures.find(v=>source===v.name+' website'||v.name===l?.venture)}if(route[0]==='client'){let l=lead(route[1]);return db.ventures.find(v=>v.name===l?.venture)}return null}
publicNav=function(){let v=brandFor(),asset=v&&V.some(x=>x[0]===v.name)?v.name==='hamzury hub'?'hub':v.name:'hamzury';return `<header class="publicnav"><a href="#${v?'expertise/'+encodeURIComponent(v.name):'home'}"><img class="logo" src="assets/${asset}.png" alt="${E(v?.name||'hamzury holding')}"></a><nav class="links"><a href="#about">who we are</a><a href="#access">my journey</a><a href="#workspace" class="button secondary">workspace</a></nav></header>`};
