home=function(){return `<div class="wrap">${publicNav()}<section class="hero"><div><div class="eyebrow">hamzury holding / business architecture</div><h1>understand it.<br>put it together.<br><em>move forward.</em></h1><p>an idea, an existing business or an organisation with a challenge. start with the situation. we guide you towards a clear, practical next step.</p><div class="actions">${button('find my next step →','form/general/new')}${button('see a sample roadmap','client/HH-JOURNEY-001/proposal','secondary')}</div><p class="small" style="margin-top:22px">questions that clarify. recommendations that explain. work you can follow.</p></div><div class="methodpaper"><div class="eyebrow">the assss approach</div>${method.map((m,i)=>`<div class="methodline"><span>0${i+1}</span><strong>${m}</strong><p>${['understand the situation','choose the direction','put the essentials in place','make the work repeatable','review the result and next step'][i]}</p></div>`).join('')}</div></section><section class="section"><div class="eyebrow">begin with your situation</div><h2>one starting point is enough.</h2><div class="grid">${[['01','i have an idea','turn the possibility into a clear starting plan.','general'],['02','i run a business','understand the gaps and choose the next useful investment.','growth'],['03','we need a solution','for organisations, contractors and people with a specific need.','direct']].map(([n,t,p,f])=>`<article class="card"><span class="number">${n}</span><h3>${t}</h3><p>${p}</p>${button('guide me →','form/'+f+'/new','ghost')}</article>`).join('')}</div></section><section class="section"><div class="sectionhead"><div><div class="eyebrow">different expertise. one business. yours.</div><h2>choose the support you want to explore.</h2></div></div><div class="grid">${db.ventures.map(v=>`<article class="card">${V.some(x=>x[0]===v.name)?`<img class="venturelogo" src="assets/${v.name==='hamzury hub'?'hub':v.name}.png" alt="${E(v.name)}">`:`<h3>${E(v.name)}</h3>`}<p>${E(v.mandate)}</p>${button('explore '+E(v.name)+' →','expertise/'+encodeURIComponent(v.name),'ghost')}</article>`).join('')}</div></section><section class="section"><div class="two"><div><div class="eyebrow">who we are</div><h2>people working together.<br>businesses moving forward.</h2><p>hamzury holding connects specialist ventures, practical learning and business support. our shared method brings a clear reason and next action to the work.</p>${button('meet hamzury →','about','secondary')}</div><div class="photoplace"><span>the people behind the work</span><p>team, lifestyle and project photographs will appear here after selection and consent.</p></div></div></section><section class="section"><div class="grid">${[['portfolio','work with a story','see the situation, approach, delivery and verified outcome.'],['voices','what people say','client and learner experiences, published with permission.'],['resources','reports & useful thinking','read our guidance, reports and downloadable resources.']].map(([p,t,d])=>`<div class="card"><h2>${t}</h2><p>${d}</p>${button('explore →',p,'ghost')}</div>`).join('')}</div></section>${footer()}</div>`};
