function venturePage(){let v=db.ventures.find(v=>v.name===decodeURIComponent(route[1]||''));if(!v)return notFound();return `<div class="wrap">${publicNav()}<section class="clientcover"><div class="eyebrow">${E(v.name)} / specialist support</div><h1>${E(v.mandate)}.</h1><p>one specialist venture within hamzury holding. the same guided approach, with its own expertise and identity.</p>${button('find my next step →','expertise/'+encodeURIComponent(v.name))}</section><div class="grid">${db.services.filter(s=>s.v===v.name).slice(0,6).map(s=>`<div class="card"><h3>${E(s.title)}</h3><p>${E(s.scope)}</p><span class="small">scope and pricing confirmed before activation.</span></div>`).join('')}</div><section class="section"><h2>the same clear journey.</h2><p>discovery, a reviewed recommendation, selectable work, requirements, progress and delivery. your record remains connected to the holding crm.</p>${button('explore this venture’s discovery routes','expertise/'+encodeURIComponent(v.name),'secondary')}</section>${footer()}</div>`}
const editorial={about:['who we are','a shared method. specialist people.','hamzury holding brings six specialist ventures together around awareness, strategy, structure, systems and success. we research the situation, recommend a practical route and support implementation.'],portfolio:['portfolio','the situation. the work. the result.','every published case study should explain the starting situation, agreed strategy, structure, systems and verified result.'],voices:['what people say','experiences worth listening to.','client and learner feedback belongs here with their permission, clear context and an accurate account of the work.'],resources:['reports & resources','useful thinking. clear next actions.','reports, guides and research can follow the same assss structure, with sources, dates, limitations and practical next steps.'],hm:['hm / personal page','the thinking behind the method.','through curiosity, pattern recognition, trial and error, the hamzury approach developed around five steps: awareness, strategy, structure, systems and success. this is the stated origin of the framework, rather than a claim of external accreditation.']};
function editorialPage(){let p=route[0],a=editorial[p],items=(db.publicContent||[]).filter(c=>c.section===p&&c.published);return `<div class="wrap">${publicNav()}<section class="clientcover"><div class="eyebrow">${a[0]}</div><h1>${a[1]}</h1><p style="max-width:760px">${a[2]}</p></section>${p==='about'?`<div class="two"><div class="photoplace"><span>team & everyday life</span><p>approved team and lifestyle photographs will be added here.</p></div><div class="card"><h2>learn from the work.</h2>${method.map((m,i)=>`<div class="row"><span class="small">0${i+1}</span><b>${m}</b></div>`).join('')}<div class="actions">${button('the origin of our approach →','hm','secondary')}</div></div></div>`:''}${p==='hm'?note('the aim is to make this approach useful across different settings. national or international recognition will be shown only when independently documented. verified achievements, biography and approved photographs can be added through the content studio.'):''}<div class="grid" style="margin-top:24px">${items.map(c=>`<article class="card">${c.image?`<img class="contentphoto" src="${E(c.image)}" alt="${E(c.title)}">`:''}<div class="eyebrow">${E(c.kind)}</div><h2>${E(c.title)}</h2><p style="white-space:pre-wrap">${E(c.body)}</p>${c.fileId?`<button onclick="downloadFile('${c.fileId}')">download resource</button>`:''}</article>`).join('')||`<div class="card"><h3>${p==='voices'?'verified feedback coming here':p==='portfolio'?'case studies prepared for publication':p==='resources'?'resource shelf ready':p==='hm'?'a place for the documented journey':'a space for the people and their work'}</h3><p>no ${p==='voices'?'testimonials':p==='portfolio'?'client results':'supporting material'} have been supplied for publication yet. the content studio is ready for approved material.</p></div>`}</div><section class="section"><div class="actions">${button('reports & resources →','resources','secondary')}${button('portfolio →','portfolio','secondary')}${button('what people say →','voices','secondary')}${button('find my next step','form/general/new')}</div></section>${footer()}</div>`}
function methodSummary(l){let have=(l.roadmapVersion?.services||[]).filter(s=>l.itemChoices?.[s.id]==='have');return [['awareness',`your situation: ${l.answers.offer||l.answers.activity||l.name}. ${l.answers.goal||'your goal needs confirmation.'}`],['strategy',l.proposalVersion?.text||'team review pending.'],['structure',`${have.length} existing item${have.length===1?'':'s'} recorded. select only the work you need.`],['systems','your chosen services move through requirements, assignment, review and delivery.'],['success','review what has been delivered, what changed and the next useful step.']]}
const olderClientView=clientView;
clientView=function(){let l=lead(route[1]);if(!l)return notFound();let page=route[2]||'proposal';if(page==='requirements')return olderClientView();let items=l.roadmapVersion?.services||[],selected=l.clientSelected||[],latest=l.updates[0];let out=`<div class="clientwrap">${publicNav()}<section class="clientcover"><div class="eyebrow">your business journey / <span class="identifier">${E(l.id)}</span></div><h1>${E(l.name)}</h1><div class="actions">${button('your recommendation','client/'+l.id+'/proposal',page==='proposal'?'':'secondary')}${button('your journey roadmap','client/'+l.id+'/roadmap',page!=='proposal'?'':'secondary')}</div></section>`;
if(page==='proposal')out+=`<article class="recommendation" id="recommendation-card"><div class="eyebrow">a note from the founder / hamzury holding</div><h2>let’s put your next step together.</h2>${methodSummary(l).map(([m,t])=>`<div class="recommendline"><span>${m}</span><p>${E(t)}</p></div>`).join('')}<div class="row"><span class="small">your reference: <b class="identifier">${E(l.id)}</b></span><span class="small">${l.proposalVersion?.preliminary?'preliminary card / team review required':l.proposalVersion?'reviewable demonstration proposal':'awaiting team review'}</span></div></article><div class="actions" style="margin:22px 0"><button onclick="downloadJourney('${l.id}','png','card')">save my card as image</button>${button('check my roadmap →','client/'+l.id+'/roadmap','secondary')}</div>${note('your reference stays with your journey. your team confirms the scope, price and requirements before activation. this is a demonstration card.')}`;
else{out+=`<div class="journeyhead"><div><div class="eyebrow">one journey / what you have, what you choose, what is done</div><h2>your full business roadmap.</h2></div><div class="actions"><button class="secondary mini" onclick="downloadJourney('${l.id}','png','roadmap')">save image</button><button class="secondary mini" onclick="downloadJourney('${l.id}','pdf','roadmap')">download pdf</button></div></div>`;if(l.paid)out+=note(`<b>your selected order is active.</b> ${E(l.next||'your team will share the next step.')} due: ${displayDate(l.due)}. remaining services stay on your roadmap for later.`);out+=`<div class="journey-layout"><div>${[0,1,2,3].map((level)=>{let list=items.filter(s=>s.level===level);if(!list.length)return '';return `<section class="journeystage"><div class="stagecaption"><span>0${level+1}</span><h2>${['minimum','standard','premium','scale & growth'][level]}</h2><span class="small">${['put the essentials in place','present and manage consistently','connect the work','prepare the next stage'][level]}</span></div><div class="card itemlist">${list.map(s=>{let w=l.work.find(w=>w.serviceId===s.id),state=w?.status||l.itemChoices?.[s.id]||((l.clientSelected||[]).includes(s.id)?'selected':'later'),files=l.files.filter(f=>w&&['review','final'].includes(f.release)&&f.workId===w.id);return `<div class="roaditem"><div class="itemtop"><div>${tag(s.v)}<h3>${E(s.title)}</h3></div><div class="itemprice">${s.price!==''?'₦'+Number(s.price).toLocaleString():'price to confirm'}</div></div><p class="small">${E(s.scope)}</p><details><summary>what you receive & what we need</summary><p class="small">${E(s.deliver)}</p><p class="small">requirements: ${E(s.req)}</p></details>${w?`<div class="row">${pill(w.status==='delivered'?'✓ delivered':w.status)}<span class="small">due: ${displayDate(w.due)}</span></div><p class="small">${E(w.evidence||'the responsible venture will publish the next update.')}</p>${files.map(f=>`<div class="row"><span class="small">${E(f.title)} · ${E(f.release)}</span><button class="mini secondary" onclick="downloadFile('${f.id}')">download here</button></div>`).join('')}`:`<div class="itemchoices"><button class="mini ${state==='selected'?'':'secondary'}" onclick="setItemChoice('${l.id}','${s.id}','selected')">${state==='selected'?'✓ selected':'add'}</button><button class="mini ${state==='have'?'':'secondary'}" onclick="setItemChoice('${l.id}','${s.id}','have')">${state==='have'?'✓ already have':'i already have this'}</button><button class="mini secondary" onclick="setItemChoice('${l.id}','${s.id}','later')">${state==='later'?'✓ later':'later'}</button></div>`}</div>`}).join('')}</div></section>`}).join('')||'<div class="card"><p>your reviewed roadmap has not been published yet.</p></div>'}</div><aside class="journeyslip"><div class="card"><div class="eyebrow">your selection</div><h2>start with what matters.</h2>${items.filter(s=>selected.includes(s.id)&&!l.work.some(w=>w.serviceId===s.id)).map(s=>`<div class="row"><span class="small">${E(s.title)}</span><b class="small">${s.price!==''?'₦'+Number(s.price).toLocaleString():'quote'}</b></div>`).join('')||'<p class="small">choose items from your roadmap.</p>'}<p class="small">${clientTotal(l)}</p>${!l.paid?`<button onclick="requestQuote('${l.id}');document.getElementById('inline-activation')?.scrollIntoView({behavior:'smooth'})">continue to activation →</button>`:`<p class="small">for extra services, request a new quotation. your active order stays unchanged.</p>`}</div><div class="card" style="margin-top:16px"><div class="eyebrow">your next action</div><h3>${E(l.next||'review and choose your next step')}</h3><p class="small">${latest?'waiting for '+E(latest.waiting):'your team will confirm scope before work begins.'}</p>${l.requirements.length?button('complete requirements →','client/'+l.id+'/requirements','secondary mini'):''}</div>${latest?`<div class="card" style="margin-top:16px"><h3>latest update</h3><p>${E(latest.message)}</p><span class="small">${displayDate(latest.at)}</span></div>`:''}</aside></div><section id="inline-activation" class="card" style="margin:24px 0"><h2>${l.paid?'your activation is confirmed in this demo.':'your selection, before payment.'}</h2><p>${l.paid?'requirements, service status and delivery downloads stay connected to your roadmap.':'your team confirms item prices, scope, terms and applicable fees. payment opens only after the formal quotation is accepted.'}</p>${pill(l.paid?'sample payment verified':'quotation and payment pending')}${note('no live payment is collected. selection, checklist and file delivery are browser-local demonstrations. the real payment provider and secure client accounts still need integration.')}</section><section class="card"><h2>your updates & next steps</h2>${l.updates.map(u=>`<div class="statusline"><span class="small">${displayDate(u.at)}</span><p>${E(u.message)}</p><p class="small">next: ${E(u.next)}</p></div>`).join('')||'<p>your team’s updates will appear here. the roadmap remains your reference throughout the work.</p>'}<form onsubmit="feedback(event,'${l.id}')"><label>feedback or correction</label><textarea name="message" required></textarea><div class="actions"><button>send feedback to the team</button></div></form></section>`}
return out+footer()+'</div>'};
function setItemChoice(id,sid,value){let l=lead(id);if(l.work.some(w=>w.serviceId===sid)){toast('this service is already in the active order');return}l.itemChoices=l.itemChoices||{};l.itemChoices[sid]=value;let a=l.clientSelected||[];l.clientSelected=value==='selected'?[...new Set([...a,sid])]:a.filter(x=>x!==sid);event(l,'roadmap item marked '+value+': '+sid);render()}
function exportLines(l,kind){let lines=[l.name,'reference: '+l.id,'hamzury holding / '+(kind==='card'?'your next step':'your business journey'),''];methodSummary(l).forEach(([m,t])=>{lines.push(m,t,'')});if(kind!=='card'){['minimum','standard','premium','scale & growth'].forEach((t,n)=>{let rows=(l.roadmapVersion?.services||[]).filter(s=>s.level===n);if(rows.length){lines.push(t);rows.forEach(s=>{let w=l.work.find(w=>w.serviceId===s.id);let status=w?.status||l.itemChoices?.[s.id]||((l.clientSelected||[]).includes(s.id)?'selected':'later');lines.push((status==='delivered'||status==='have'?'[done] ':'[ ] ')+s.title+' / '+s.v+' / '+(s.price!==''?'NGN '+Number(s.price).toLocaleString():'price to confirm')+' / '+status);if(w?.due)lines.push('expected delivery: '+displayDate(w.due))});lines.push('')}})}lines.push('next action: '+(l.next||'review your roadmap with the team'),'demonstration record. no payment or external recognition is implied.');return lines}
function wrapWords(text,max){let a=[],line='';for(let w of text.split(/\s+/)){if((line+' '+w).length>max&&line){a.push(line);line=w}else line+=(line?' ':'')+w}if(line)a.push(line);return a}
function downloadBlob(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function downloadJourney(id,type,kind){let l=lead(id),lines=exportLines(l,kind);if(type==='png'){let rows=lines.flatMap(x=>wrapWords(x,80).length?wrapWords(x,80):['']),c=document.createElement('canvas');c.width=1080;c.height=Math.max(1000,rows.length*30+220);let x=c.getContext('2d');x.fillStyle='#f8f3eb';x.fillRect(0,0,c.width,c.height);x.fillStyle='#b99770';x.fillRect(0,0,248,8);x.fillStyle='#3b241a';x.fillRect(248,0,832,8);try{let im=new Image();im.src='assets/hamzury.png';await im.decode();x.drawImage(im,65,40,260,260*im.height/im.width)}catch{}x.fillStyle='#3b241a';let y=135;rows.forEach((t,i)=>{x.font=(i===0?'500 29px':'19px')+' Arial';x.fillText(t,65,y);y+=30});x.strokeStyle='#e1d6c9';x.beginPath();x.moveTo(65,c.height-65);x.lineTo(1015,c.height-65);x.stroke();x.font='15px Arial';x.fillText('awareness / strategy / structure / systems / success',65,c.height-35);c.toBlob(b=>{downloadBlob(b,l.id+'-'+kind+'.png');toast('your image has been prepared')},'image/png');return}
let rows=lines.flatMap(t=>wrapWords(t.replace(/[^\x20-\x7E]/g,' '),92).length?wrapWords(t.replace(/[^\x20-\x7E]/g,' '),92):['']);let pages=[];for(let i=0;i<rows.length;i+=43)pages.push(rows.slice(i,i+43));let objects=['<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];let pageIds=[];for(let page of pages){let pid=objects.length+1,cid=pid+1;pageIds.push(pid);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${cid} 0 R >>`);let text='0.973 0.953 0.922 rg 0 0 595 842 re f\n0.725 0.592 0.439 rg 0 837 137 5 re f\n0.231 0.141 0.102 rg 137 837 458 5 re f\nBT /F1 17 Tf 42 790 Td (hamzury holding) Tj ET\nBT /F1 10 Tf 14 TL 42 756 Td\n'+page.map(t=>'('+t.replace(/[\\()]/g,'\\$&')+') Tj T*').join('\n')+'\nET\nBT /F1 8 Tf 42 34 Td (awareness / strategy / structure / systems / success) Tj ET';objects.push('<< /Length '+text.length+' >>\nstream\n'+text+'\nendstream')}objects[1]='<< /Type /Pages /Kids ['+pageIds.map(i=>i+' 0 R').join(' ')+'] /Count '+pages.length+' >>';let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});let at=pdf.length;pdf+='xref\n0 '+(objects.length+1)+'\n0000000000 65535 f \n'+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(objects.length+1)+' /Root 1 0 R >>\nstartxref\n'+at+'\n%%EOF';downloadBlob(new Blob([pdf],{type:'application/pdf'}),l.id+'-'+kind+'.pdf');toast('your pdf has been prepared')}
const originalDiscoveryView=discoveryView;
discoveryView=function(){let html=originalDiscoveryView();let f=db.forms.find(f=>f.id===route[1]),l=lead((route[2]||'').split('?')[0]),pub=l?.discoverySnapshot||f?.published||f,q=pub?.qs[formStep];if(q){let education=/sales|customer|enquir|follow/i.test(q.label)?'more attention helps when the offer and follow-up process can turn interest into suitable sales. tell us what happens today.':/existing|already|asset|tool/i.test(q.label)?'what you already have matters. we check existing assets before recommending more work.':/goal|vision|achiev|become/i.test(q.label)?'a useful plan starts with a result you can describe. you can be uncertain; we will help clarify it.':'your answer helps us understand the situation before recommending the next step.';html=html.replace('<h3>what happens next?</h3>',`<div class="eyebrow">awareness / understand before investing</div><h3>why we ask</h3><p>${education}</p><h3>what happens next?</h3>`)}return html};
const originalNextAnswer=nextAnswer;
nextAnswer=function(e,fid,id){let f=db.forms.find(f=>f.id===fid),pub=lead(id)?.discoverySnapshot||f?.published||f,last=formStep===pub.qs.length-1;originalNextAnswer(e,fid,id);if(!last)return;let l=lead(id)||db.leads.find(l=>formAnswers._contact&&l.contact.toLowerCase()===formAnswers._contact.trim().toLowerCase());if(!l)return;if(!l.proposalVersion){let goal=l.answers.goal||l.answers.service||l.answers.need||'the situation you described';l.proposalVersion={text:'thank you for sharing your situation. your immediate focus is '+goal+'. our next step is to check the information, clarify what you already have and recommend a practical sequence. your team will review the scope, prices and requirements before any work is activated.',version:1,at:now(),preliminary:true};l.next='team reviews discovery and prepares the itemized roadmap';event(l,'preliminary acknowledgement card prepared; team review required')}go('client/'+l.id+'/proposal')};
function contentStudio(){let cs=db.publicContent||[];return title('content studio','publish the real story.','approved photographs, founder material, reports, portfolio and feedback. no invented endorsements.')+`<div class="two"><form class="card" onsubmit="publishContent(event)"><label>section</label><select name="section">${Object.entries(editorial).map(([k,a])=>`<option value="${k}">${a[0]}</option>`).join('')}</select><label>content type</label><select name="kind"><option>team & lifestyle</option><option>founder note</option><option>case study</option><option>client feedback</option><option>report</option><option>guide</option><option>achievement</option></select><label>title</label><input name="title" required><label>story or summary</label><textarea name="body" required placeholder="awareness: situation. strategy: approach. structure: essentials. systems: implementation. success: evidenced outcome."></textarea><label>approved photo, optional</label><input name="image" type="file" accept="image/png,image/jpeg,image/webp"><label>report or supporting file, optional</label><input name="resource" type="file"><label class="checkrow"><input name="consent" type="checkbox" required> publication permission and factual claims checked</label><div class="actions"><button>publish sample content</button></div>${note('use non-sensitive test files. this content is saved in this browser only. live publishing requires shared secure storage and authorization.')}</form><div class="card"><h2>published content register</h2>${cs.map(c=>`<div class="row"><div><h3>${E(c.title)}</h3><span class="small">${E(c.section)} / ${E(c.kind)}</span></div><button class="secondary mini" onclick="toggleContent('${c.id}')">${c.published?'unpublish':'publish'}</button></div>`).join('')||'<p>no editorial content published yet.</p>'}</div></div>`}
async function publishContent(e){e.preventDefault();let d=new FormData(e.target),im=d.get('image'),file=d.get('resource'),c={id:uid('content'),section:d.get('section'),kind:d.get('kind'),title:d.get('title'),body:d.get('body'),published:true,at:now()};if(im?.size){if(im.size>1024*1024){toast('use a sample photograph smaller than 1 mb');return}if(!['image/png','image/jpeg','image/webp'].includes(im.type)){toast('choose a png, jpeg or webp photograph');return}c.image=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(im)})}if(file?.size){if(file.size>2*1024*1024){toast('use a sample resource smaller than 2 mb');return}let fid=uid('resource'),idb=await filesDB;await new Promise((res,rej)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(file,fid);tx.oncomplete=res;tx.onerror=rej});c.fileId=fid}db.publicContent=db.publicContent||[];db.publicContent.unshift(c);save();render();toast('sample editorial content published in this browser')}
function toggleContent(id){let c=db.publicContent.find(c=>c.id===id);c.published=!c.published;save();render()}
navs.splice(navs.length-1,0,['content','content studio']);
const existingRender=render;
render=function(){route=location.hash.slice(1).split('/');let p=route[0]||'home';if(p==='expertise')root.innerHTML=demo()+expertise();else if(p==='venture-page')root.innerHTML=demo()+venturePage();else if(editorial[p])root.innerHTML=demo()+editorialPage();else if(p==='content')root.innerHTML=demo()+workspace(contentStudio());else existingRender();let v=brandFor();if(p==='venture-page')v=db.ventures.find(v=>v.name===decodeURIComponent(route[1]||''));document.documentElement.style.setProperty('--choc',v?.color||'#3b241a');document.documentElement.style.setProperty('--accent',v?'#e1e8e6':'#b99770');document.documentElement.style.setProperty('--milk',v?'#f6f8fa':'#f8f3eb');attachLabels()};
render();
